WITH filtered_employees AS (SELECT *, LOWER(job_title) AS job_title_lower FROM employees WHERE level = 'L3' AND email LIKE '%@yahoo.com' AND manager_id IS NOT NULL), is_remote_summary AS (SELECT is_remote, SUM(CASE WHEN level = 'L2' THEN 1 ELSE 0 END) AS l2_count, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(level))) AS level_values FROM filtered_employees GROUP BY is_remote) SELECT * FROM is_remote_summary ORDER BY 3 DESC;
